def next_generation(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    result = []
    for r in range(rows):
        row = []
        for c in range(cols):
            alive = 0
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if (dr, dc) == (0, 0):
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        alive += grid[nr][nc]
            if grid[r][c] == 1:
                row.append(1 if alive in (2, 3) else 0)
            else:
                row.append(1 if alive == 3 else 0)
        result.append(row)
    return result

